import { useState } from "react";
import {
    BrowserRouter,
    Routes,
    Route,
    Link,
    useParams,
    useNavigate,
} from "react-router-dom";
import "./taskflow.css";

/* ---------- Task List View ("/") ---------- */
function TaskList({ tasks, addTask, toggleTask, editTask, deleteTask }) {
    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [error, setError] = useState("");

    function handleSubmit(e) {
        e.preventDefault();
        if (newTask.trim() === "") {
            setError("Task title can't be empty.");
            return;
        }
        addTask(newTask.trim());
        setNewTask("");
        setError("");
    }

    const filteredTasks = tasks.filter((t) =>
        t.title.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="card">
            <h2>List View — "/"</h2>

            <input
                className="text-box"
                type="text"
                placeholder="Search tasks..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />

            <form className="add-row" onSubmit={handleSubmit}>
                <input
                    className="text-box"
                    type="text"
                    placeholder="Add a new task..."
                    value={newTask}
                    onChange={(e) => setNewTask(e.target.value)}
                />
                <button className="add-btn" type="submit">
                    Add
                </button>
            </form>
            {error && <p className="error">{error}</p>}

            {filteredTasks.map((task) => (
                <div className="task" key={task.id}>
                    <label className="task-title">
                        <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => toggleTask(task.id)}
                        />
                        <Link
                            to={`/tasks/${task.id}`}
                            className={task.completed ? "done" : ""}
                        >
                            {task.title}
                        </Link>
                    </label>

                    <div className="task-buttons">
                        <button onClick={() => editTask(task.id, task.title)}>Edit</button>
                        <button onClick={() => deleteTask(task.id)}>Delete</button>
                    </div>
                </div>
            ))}

            {filteredTasks.length === 0 && <p className="empty">No tasks found.</p>}
        </div>
    );
}

function TaskDetail({ tasks, toggleTask, deleteTask }) {
    const { id } = useParams();
    const navigate = useNavigate();
    const task = tasks.find((t) => t.id === Number(id));

    if (!task) {
        return (
            <div className="card">
                <h2>Task not found</h2>
                <Link to="/" className="back-link">
                    ← Back to list
                </Link>
            </div>
        );
    }

    const created = new Date(task.createdAt).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
    });

    function handleDelete() {
        deleteTask(task.id);
        navigate("/");
    }

    return (
        <div className="card">
            <h2>Detail View — "/tasks/:id"</h2>
            <Link to="/" className="back-link">
                ← Back to list
            </Link>

            <p className="label">Title</p>
            <p className="value">{task.title}</p>

            <p className="label">Status</p>
            <p className="value">{task.completed ? "Completed" : "Pending"}</p>

            <p className="label">Created</p>
            <p className="value">{created}</p>

            <div className="detail-buttons">
                <button onClick={() => toggleTask(task.id)}>
                    {task.completed ? "Mark as Pending" : "Mark as Completed"}
                </button>
                <button onClick={handleDelete}>Delete</button>
            </div>
        </div>
    );
}

/* ---------- Main component ---------- */
function Taskflow() {
    const [tasks, setTasks] = useState([
        { id: 1, title: "Set up project repo", completed: false, createdAt: "2026-11-03T12:00:00" },
        { id: 2, title: "Write feature list", completed: true, createdAt: "2026-11-03T12:00:00" },
        { id: 3, title: "Build add-task form", completed: false, createdAt: "2026-11-03T12:00:00" },
    ]);

    function addTask(title) {
        setTasks([
            ...tasks,
            { id: Date.now(), title: title, completed: false, createdAt: new Date().toISOString() },
        ]);
    }

    function toggleTask(id) {
        setTasks(tasks.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t)));
    }

    function editTask(id, oldTitle) {
        const title = prompt("Edit task:", oldTitle);
        if (title === null || title.trim() === "") return;
        setTasks(tasks.map((t) => (t.id === id ? { ...t, title: title } : t)));
    }

    function deleteTask(id) {
        setTasks(tasks.filter((t) => t.id !== id));
    }

    return (
        <BrowserRouter>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            <Routes>
                <Route
                    path="/"
                    element={
                        <TaskList
                            tasks={tasks}
                            addTask={addTask}
                            toggleTask={toggleTask}
                            editTask={editTask}
                            deleteTask={deleteTask}
                        />
                    }
                />
                <Route
                    path="/tasks/:id"
                    element={
                        <TaskDetail tasks={tasks} toggleTask={toggleTask} deleteTask={deleteTask} />
                    }
                />
            </Routes>
        </BrowserRouter>
    );
}

export default Taskflow;
